ective)==='index,follow')>index, follow</option><option value="noindex,follow" @selected(old('robots_directive',$page->robots_directive)==='noindex,follow')>noindex, follow</option><option value="noindex,nofollow" @selected(old('robots_directive',$page->robots_directive)==='noindex,nofollow')>noindex, nofollow</option></select></div><div class="mb-3"><label class="form-label" for="page-og-title">Social sharing title</label><input class="form-control" id="page-og-title" name="og_title" value="{{ old('og_title',$page->og_title) }}" maxlength="120"></div><div class="mb-3"><label class="form-label" for="page-og-media">Social sharing image</label><select class="form-select" id="page-og-media" name="og_media_id"><option value="">Use global social-sharing image</option>@foreach(\App\Support\MediaPicker::query()->latest()->orderByDesc("id")->get()->filter(fn ($asset) => \App\Support\MediaPicker::fileExists($asset)) as $asset)<option value="{{ $asset->id }}" @selected((string)old('og_media_id',$page->og_media_id)===(string)$asset->id)>{{ $asset->original_name }}</option>@endforeach</select>@if($page->og_media_id && ! \App\Support\MediaPicker::find($page->og_media_id))<div class="form-text text-warning-emphasis" data-sharing-image-unavailable>The sharing image chosen earlier is no longer available (deleted, missing or not an image). Choose another, or save with the global image.</div>@endif</div><div class="mb-3"><label class="form-label" for="page-og-description">Social sharing description</label><textarea class="form-control" id="page-og-description" name="og_description" rows="2" maxlength="320">{{ old('og_description',$page->og_description) }}</textarea></div><button class="btn btn-kelika w-100">Save Page Settings</button></form><div class="mt-4 small"><div><strong>Public URL</strong></div><code>/{{ $page->slug==='home'?'':$page->slug }}</code><hr><div><strong>Last updated</strong></div>{{ $page->updated_at?->format('d M Y, H:i') }}</div></div><div class="admin-panel mt-4" id="revisions"><h2 class="h6 fw-bold">Saved revisions</h2><p class="small text-secondary">Each revision is this page as it was just before a change. Restoring one replaces the page settings and sections it recorded; the current version is saved first, so a restore can be undone.</p>@forelse($page->revisions->take(10) as $revision)@php($revisionData = is_array($revision->snapshot) ? $revision->snapshot : [])<div class="small border-bottom py-2 d-flex justify-content-between align-items-start gap-2"><div><strong>{{ $revision->revision_label ?? 'Saved revision' }}</strong><div class="text-secondary">{{ $revision->user?->name ?? 'System' }} · {{ $revision->created_at->format('d M Y H:i') }}</div><div class="text-secondary">@if(isset($revisionData['page']['status']))Status: {{ ucfirst($revisionData['page']['status']) }} · @endif{{ isset($revisionData['sections']) && is_array($revisionData['sections']) ? count($revisionData['sections']).' '.\Illuminate\Support\Str::plural('section', count($revisionData['sections'])) : 'no sections recorded' }}</div></div><form method="post" action="{{ route('admin.pages.revisions.restore', [$page, $revision]) }}">@csrf<button class="btn btn-sm btn-outline-secondary" data-confirm="Restore the version from {{ $revision->created_at->format('d M Y H:i') }}? The page settings and sections it recorded will replace the current ones. The current version is saved as a revision first, so you can undo this.">Restore</button></form></div>@empty<p class="small text-secondary mb-0">Revisions are created when page settings or sections are saved.</p>@endforelse @if($page->revisions->count() > 10)<p class="small text-secondary mt-2 mb-0">{{ $page->revisions->count() - 10 }} older {{ \Illuminate\Support\Str::plural('revision', $page->revisions->count() - 10) }} kept and not listed.</p>@endif</div></div></div>@endsection
